        "obligation_count": len(obligations),
        "trust_declaration_count": len(declared),
        "designated_sorry_count": 0,
        "diagnostics": diagnostics,
    }


def run_preflight(
    frozen_input: Path,
    discovery_manifest: Path,
    generation: Path,
    *,
    toolchain_lock: Path,
    run_command: Callable[..., tuple[int, str]] = _run,
) -> dict[str, Any]:
    frozen_input = Path(frozen_input)
    discovery_manifest = Path(discovery_manifest)
    generation = Path(generation)
    output = generation / "preflight.json"
    if output.exists() or output.is_symlink():
        raise KleanPreflightError(f"preflight result already exists: {output}")

    def error_document(error: KleanPreflightError) -> dict[str, Any]:
        try:
            stage1_hash = klean_export.tree_digest(frozen_input)
        except (OSError, klean_export.KleanExportError):
            stage1_hash = None
        try:
            stage3_hash = hashlib.sha256(
                discovery_manifest.read_bytes()
            ).hexdigest()
        except OSError:
            stage3_hash = None
        return {
            "schema_version": 3,
            "status": "KLEAN_PREFLIGHT_ERROR",
            "error": str(error),
            "stage1_workspace_sha256": stage1_hash,
            "stage3_discovery_manifest_sha256": stage3_hash,
        }

    publication_snapshot: PreflightSnapshot | None = None
    try:
        publication_snapshot = _preflight_snapshot(
            frozen_input, discovery_manifest, generation
        )
        document = check_generation(
            frozen_input,
            discovery_manifest,
            generation,
            toolchain_lock=toolchain_lock,
            run_command=run_command,
        )
        _require_unchanged_snapshot(
            publication_snapshot,
            frozen_input,
            discovery_manifest,
            generation,
        )
    except KleanPreflightError as error:
        document = error_document(error)
    temporary = output.with_name(f".{output.name}.tmp")
    temporary.write_text(json.dumps(document, indent=2, sort_keys=True) + "\n")
    if (
        document.get("status") in {"PASS", "KLEAN_NO_OBLIGATIONS"}
        and publication_snapshot is not None
    ):
        try:
            _require_unchanged_snapshot(
                publication_snapshot,
                frozen_input,
                discovery_manifest,
                generation,
            )
        except KleanPreflightError as error:
            document = error_document(error)
            temporary.write_text(
                json.dumps(document, indent=2, sort_keys=True) + "\n"
            )
    os.replace(temporary, output)
    return document


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", required=True, type=Path)
    parser.add_argument("--discovery-manifest", required=True, type=Path)
    parser.add_argument("--generation", required=True, type=Path)
    parser.add_argument(
        "--toolchain-lock",
        type=Path,
        default=REPO / "data/klean-toolchain.lock.json",
    )
    arguments = parser.parse_args(argv)
    try:
        result = run_preflight(
            arguments.input,
            arguments.discovery_manifest,
            arguments.generation,
            toolchain_lock=arguments.toolchain_lock,
        )
    except KleanPreflightError as error:
        print(f"Klean preflight failed: {error}", file=sys.stderr)
        return 2
    print(json.dumps(result, sort_keys=True))
    return (
        0
        if result["status"] in {"PASS", "KLEAN_NO_OBLIGATIONS"}
        else 1
    )


if __name__ == "__main__":
    raise SystemExit(main())

def _required_local_files(masked_text: str) -> list[str]:
    """Workspace-root .k files pulled in by requires clauses, in order."""

    names: list[str] = []
    for match in re.finditer(r'(?m)^\s*requires\s+"([^"]+)"', masked_text):
        name = match.group(1)
        if "/" in name or not name.endswith(".k"):
            continue
        if name not in names:
            names.append(name)
    return names


def inventory_verification(workspace: Path) -> dict[str, Any]:
    workspace = Path(workspace)
    try:
        workspace_mode = workspace.stat(follow_symlinks=False).st_mode
    except OSError as error:
        raise KRuleInventoryError(
            f"workspace must be a real directory: {workspace}"
        ) from error
    if not stat.S_ISDIR(workspace_mode):
        raise KRuleInventoryError(
            f"workspace must be a real directory: {workspace}"
        )

    loaded: dict[str, tuple[bytes, str, str]] = {}
    order: list[str] = []

    def load_file(name: str) -> None:
        if name in loaded:
            return
        path = workspace / name
        try:
            mode = path.stat(follow_symlinks=False).st_mode
        except OSError as error:
            if name == "verification.k":
                raise KRuleInventoryError(
                    f"workspace has no regular verification.k: {path}"
                ) from error
            return
        if not stat.S_ISREG(mode):
            if name == "verification.k":
                raise KRuleInventoryError(
                    f"workspace has no regular verification.k: {path}"
                )
            return
        try:
            raw = path.read_bytes()
            text = raw.decode()
        except (OSError, UnicodeError) as error:
            raise KRuleInventoryError(
                f"cannot read local K file: {path}"
            ) from error
        masked = _mask_non_code(text)
        loaded[name] = (raw, text, masked)
        order.append(name)
        for required in _required_local_files(_without_comments(text)):
            load_file(required)

    load_file("verification.k")

    module_files: dict[str, str] = {}
    modules_by_file: dict[str, tuple[_Module, ...]] = {}
    all_modules: list[_Module] = []
    for name in order:
        file_modules = _modules(loaded[name][2])
        modules_by_file[name] = file_modules
        for file_module in file_modules:
            if file_module.name in module_files:
                raise KRuleInventoryError(
                    "duplicate module across local K files: "
                    + file_module.name
                )
            module_files[file_module.name] = name
        all_modules.extend(file_modules)

    module = _verification_module(
        modules_by_file["verification.k"],
        _last_verification_main_module(workspace),
    )
    closure = _verification_closure(tuple(all_modules), module)
    closure_names = {closure_module.name for closure_module in closure}
    rule_documents: list[dict[str, Any]] = []
    for name in order:
        file_closure = tuple(
            file_module
            for file_module in modules_by_file[name]
            if file_module.name in closure_names
        )
        documents = _rule_documents(loaded[name][1], file_closure)
        if name != "verification.k":
            for document in documents:
                document["file"] = name
        rule_documents.extend(documents)

    result: dict[str, Any] = {
        "schema_version": 2,
        "verification_file": "verification.k",
        "verification_sha256": hashlib.sha256(
            loaded["verification.k"][0]
        ).hexdigest(),
        "verification_module": module.name,
        "verification_modules": [
            closure_module.name for closure_module in closure
        ],
        "rules": rule_documents,
        "inventory_sha256": canonical_json_sha256(rule_documents),
    }
    extra_files = [name for name in order if name != "verification.k"]
    if extra_files:
        result["required_files_sha256"] = {
            name: hashlib.sha256(loaded[name][0]).hexdigest()
            for name in extra_files
        }
    return result
#!/usr/bin/env python3
"""Validate Stage 3 classifications against the canonical K rule inventory."""

from __future__ import annotations

import json
import stat
from pathlib import Path
from typing import Any

from tools.k_rule_inventory import KRuleInventoryError, inventory_verification


_MANIFEST_KEYS = {"schema_version", "inventory_sha256", "rules"}
_RULE_KEYS = {"source_rule_id", "classification", "rationale"}
_CLASSIFICATIONS = {
    "DEFINITION",
    "OPERATIONAL_RULE",
    "PROVED_DERIVED_LEMMA",
    "DOMAIN_LEMMA",
}


class LemmaDiscoveryContractError(RuntimeError):
    """Raised when a Stage 3 manifest crosses its trust boundary."""


def _regular_json(path: Path) -> dict[str, Any]:
    path = Path(path)
    try:
        mode = path.stat(follow_symlinks=False).st_mode
    except OSError as error:
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest must be a regular file: {path}"
        ) from error
    if not stat.S_ISREG(mode):
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest must be a regular file: {path}"
        )
    try:
        document = json.loads(path.read_bytes())
    except (OSError, UnicodeError, ValueError) as error:
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest is malformed: {path}"
        ) from error
    if not isinstance(document, dict):
        raise LemmaDiscoveryContractError(
            "lemma discovery manifest must be a JSON object"
        )
    return document


def _exact_keys(
    document: dict[str, Any], expected: set[str], label: str
) -> None:
    unexpected = sorted(set(document) - expected)
    if unexpected:
        raise LemmaDiscoveryContractError(
            f"{label} has unexpected key: {unexpected[0]}"
        )
    missing = sorted(expected - set(document))
    if missing:
        raise LemmaDiscoveryContractError(
            f"{label} is missing key: {missing[0]}"
        )


def validate_trust_boundary(
    workspace: Path, manifest: Path
) -> dict[str, Any]:
    try:
        inventory = inventory_verification(Path(workspace))
    except KRuleInventoryError as error:
        raise LemmaDiscoveryContractError(str(error)) from error
    document = _regular_json(Path(manifest))
    _exact_keys(document, _MANIFEST_KEYS, "lemma discovery manifest")
    schema_version = document["schema_version"]
    if (
        not isinstance(schema_version, int)
        or isinstance(schema_version, bool)
        or schema_version != 2
    ):
        raise LemmaDiscoveryContractError(
            "lemma discovery schema_version must be 2"
        )
    if document["inventory_sha256"] != inventory["inventory_sha256"]:
        raise LemmaDiscoveryContractError(
            "lemma discovery inventory_sha256 does not match canonical inventory"
        )
    entries = document["rules"]
    if not isinstance(entries, list):
        raise LemmaDiscoveryContractError(
            "lemma discovery rules must be a JSON list"
        )
    canonical_rules = inventory["rules"]
    canonical_by_id = {
        rule["source_rule_id"]: rule for rule in canonical_rules
    }
    classified_by_id: dict[str, dict[str, str]] = {}
    for index, entry in enumerate(entries):
        label = f"lemma discovery rule {index}"
        if not isinstance(entry, dict):
            raise LemmaDiscoveryContractError(f"{label} must be an object")
        _exact_keys(entry, _RULE_KEYS, label)
        source_rule_id = entry["source_rule_id"]
        if not isinstance(source_rule_id, str) or not source_rule_id:
            raise LemmaDiscoveryContractError(
                f"{label} source_rule_id must be a nonempty string"
            )
        if source_rule_id in classified_by_id:
            raise LemmaDiscoveryContractError(
                f"duplicate lemma discovery source_rule_id: {source_rule_id}"
            )
        if source_rule_id not in canonical_by_id:
            raise LemmaDiscoveryContractError(
                f"unknown lemma discovery source_rule_id: {source_rule_id}"
            )
        classification = entry["classification"]
        if (
            not isinstance(classification, str)
            or classification not in _CLASSIFICATIONS
        ):
            raise LemmaDiscoveryContractError(
                f"{label} classification must be DEFINITION, "
                "OPERATIONAL_RULE, PROVED_DERIVED_LEMMA, or DOMAIN_LEMMA"
            )
        canonical_rule = canonical_by_id[source_rule_id]
        if (
            "simplification" in canonical_rule["attributes"]
            and classification
            in {"OPERATIONAL_RULE", "PROVED_DERIVED_LEMMA"}
        ):
            raise LemmaDiscoveryContractError(
                f"{label} simplification rule must be classified as "
                "DEFINITION or DOMAIN_LEMMA"
            )
        rationale = entry["rationale"]
        if not isinstance(rationale, str) or not rationale.strip():
            raise LemmaDiscoveryContractError(
                f"{label} rationale must be a nonempty string"
            )
        classified_by_id[source_rule_id] = {
            "classification": classification,
            "rationale": rationale,
        }
    missing = [
        rule["source_rule_id"]
        for rule in canonical_rules
        if rule["source_rule_id"] not in classified_by_id
    ]
    if missing:
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest is missing source_rule_id: {missing[0]}"
        )
    definitions: list[dict[str, Any]] = []
    operational_rules: list[dict[str, Any]] = []
    proved_derived_lemmas: list[dict[str, Any]] = []
    domain_lemmas: list[dict[str, Any]] = []
    for rule in canonical_rules:
        classification = classified_by_id[rule["source_rule_id"]]
        classified_rule = {**rule, **classification}
        role = classification["classification"]
        if role == "DEFINITION":
            definitions.append(classified_rule)
        elif role == "OPERATIONAL_RULE":
            operational_rules.append(classified_rule)
        elif role == "PROVED_DERIVED_LEMMA":
            proved_derived_lemmas.append(classified_rule)
        else:
            domain_lemmas.append(classified_rule)
    return {
        **inventory,
        "definitions": definitions,
        "operational_rules": operational_rules,
        "proved_derived_lemmas": proved_derived_lemmas,
        "domain_lemmas": domain_lemmas,
    }

