    except PipelineContractError:
        remove_published_destination()
        raise
    except OSError as error:
        remove_published_destination()
        raise PipelineContractError(
            f"cannot preserve runtime metrics: {error}"
        ) from error
    except BaseException:
        remove_published_destination()
        raise
    finally:
        try:
            temporary.unlink()
        except OSError:
            pass
        except BaseException:
            remove_published_destination()
            raise


